import { listTools } from './server.mjs';
import { callTool } from './server.mjs';

const tools = await listTools();
console.log('listTools =>', JSON.stringify(tools, null, 2));

// strict schema checks
for (const t of tools) {
  console.log('has additionalProperties=false:', t.inputSchema.additionalProperties === false);
  console.log('has type/properties/required:', t.inputSchema.type === 'object' && t.inputSchema.properties && Array.isArray(t.inputSchema.required));
}

// unknown tool
try { await callTool('nope', {}); console.log('UNEXPECTED accept'); }
catch (e) { console.log('unknown tool rejected:', e.message); }

// missing file
try { await callTool('file_metadata', { path: 'nope.txt' }); console.log('UNEXPECTED'); }
catch (e) { console.log('missing rejected:', e.message); }

// traversal
try { await callTool('file_metadata', { path: '../package.json' }); console.log('UNEXPECTED'); }
catch (e) { console.log('traversal rejected:', e.message); }

// traversal via absolute path
try { await callTool('file_metadata', { path: '/etc/passwd' }); console.log('UNEXPECTED'); }
catch (e) { console.log('absolute rejected:', e.message); }

// unknown extra prop
try { await callTool('file_metadata', { path: 'readme.txt', extra: 1 }); console.log('UNEXPECTED'); }
catch (e) { console.log('extra rejected:', e.message); }

// ok
try {
  const r = await callTool('file_metadata', { path: 'readme.txt' });
  console.log('OK readme ->', r.content[0].text);
} catch(e) { console.log('unexpected err', e.message); }

try {
  const r = await callTool('file_metadata', { path: 'config.JSON' });
  console.log('OK config.JSON ->', r.content[0].text);
} catch(e) { console.log('unexpected err', e.message); }
"
"}

